    idxpool: Vec<usize>,
    /// Number of indices currently pushed onto the pool (top pointer).
    idxptr: usize,
    /// Next fresh index to allocate.
    idxmax: usize,
    /// Maximum number of nodes.
    maxn: usize,
    /// Alphabet size.
    alphsz: usize,
    /// Hash table capacity.
    ecap: usize,
